import{_ as r,a0 as s,w as p,s as a,ao as o,I as n,x as u,a1 as l,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const B=JSON.parse('{"title":"3種方法來創建輕量、持久化的Xubuntu Linux USB系統盤 | LCTT x X-CMD","titleTemplate":false,"description":"3種方法來創建輕量、持久化的Xubuntu Linux USB系統盤 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"3種方法來創建輕量、持久化的Xubuntu Linux USB系統盤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"3種方法來創建輕量、持久化的Xubuntu Linux USB系統盤 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20150119 3 Ways To Create A Lightweight And Persistent Xubuntu Linux USB Drive","title":"3種方法來創建輕量、持久化的Xubuntu Linux USB系統盤","tag":"201502","desc":""},"relativePath":"201502/20150119 3 Ways To Create A Lightweight And Persistent Xubuntu Linux USB Drive.md","filePath":"[post].md"}'),b={name:"201502/20150119 3 Ways To Create A Lightweight And Persistent Xubuntu Linux USB Drive.md"};function d(x,t,U,S,m,T){const i=s("Link");return p(),a("div",null,[t[35]||(t[35]=o('<h1 id="_3種方法來創建輕量、持久化的xubuntu-linux-usb系統盤" tabindex="-1">3種方法來創建輕量、持久化的Xubuntu Linux USB系統盤 <a class="header-anchor" href="#_3種方法來創建輕量、持久化的xubuntu-linux-usb系統盤" aria-label="Permalink to “3種方法來創建輕量、持久化的Xubuntu Linux USB系統盤”">​</a></h1><h3 id="使用universal-usb-install創建持久化usb-xubuntu系統盤" tabindex="-1">使用Universal USB Install創建持久化USB Xubuntu系統盤 <a class="header-anchor" href="#使用universal-usb-install創建持久化usb-xubuntu系統盤" aria-label="Permalink to “使用Universal USB Install創建持久化USB Xubuntu系統盤”">​</a></h3><p><img src="http://f.tqn.com/y/linux/1/S/2/J/1/xubuntudesktop.png" alt=""></p>',3)),n("p",null,[t[1]||(t[1]=u("這個教程為你介紹如何使用Xubuntu Linux創建一個輕量並且",-1)),l(i,{href:"http://www.pendrivelinux.com/what-is-persistent-linux/"},{default:e(()=>[...t[0]||(t[0]=[u("持久化",-1)])]),_:1}),t[2]||(t[2]=u("的Linux USB系統盤。",-1))]),t[36]||(t[36]=o('<blockquote><p>譯者注：持久化Linux USB系統盤（Persistent Linux USB drive），安裝在優盤的Linux系統，允許用户保存數據到優盤而不是僅僅將這些修改留在內存中。這些數據可以在重啓後恢復並且重新使用，甚至是在其他的機器上面啓動也沒有關係。一般情況下，持久化系統盤會安裝一個壓縮過的Linux操作系統。</p></blockquote><p>為什麼要這樣做呢，這裏有5個很好的理由：</p><ol><li>你想要在你的電腦上安裝一個輕量並且功能完善的Linux版本。</li><li>你的電腦沒有硬盤，那麼一個Linux USB系統盤就可以讓這台電腦擺脱被扔到垃圾堆的命運。</li><li>你想體驗一下Linux，但是你卻不想花太多的時間去準備。</li><li>你想創建一個USB系統恢復盤，並且在優盤上安裝一些特定的應用程序。</li><li>你想要一個可定製的Linux版本，能裝在後兜或者掛在鑰匙圈上。</li></ol><p>現在，我們有了充足的理由，那麼開始做一些準備工作吧。</p><p>如果你使用的是Windows：</p><ol><li>下載Xubuntu。</li><li>下載Universal USB Installer。</li><li>插入一個空的優盤。</li><li>使用Universal USB Installer創建一個常駐系統啓動盤。</li></ol><p>如果你使用的是Ubuntu：</p><ol><li>下載Xubuntu。</li><li>使用Ubuntu Startup Creator。</li></ol><p>如果你使用的是其他版本的Linux：</p><ol><li>下載Xubuntu。</li><li>使用UNetbootin。</li></ol><p>還有一些場景，可能需要使用命令列，會更難一些，但是上面列的三種應該已經可以滿足大部分的情況。</p><h3 id="下載xubuntu和universal-usb-installer" tabindex="-1">下載Xubuntu和Universal USB Installer <a class="header-anchor" href="#下載xubuntu和universal-usb-installer" aria-label="Permalink to “下載Xubuntu和Universal USB Installer”">​</a></h3><p><img src="http://f.tqn.com/y/linux/1/S/G/J/1/xubuntuwebsite.JPG" alt=""></p>',13)),n("p",null,[t[4]||(t[4]=u("訪問",-1)),l(i,{href:"http://xubuntu.org/getxubuntu/"},{default:e(()=>[...t[3]||(t[3]=[u("Xubuntu網站",-1)])]),_:1}),t[5]||(t[5]=u("，然後選一個你喜歡的版本下載。",-1))]),t[37]||(t[37]=n("p",null,"目前有兩個版本可供使用：",-1)),n("ul",null,[n("li",null,[l(i,{href:"http://www.dedoimedo.com/computers/xubuntu-trusty.html"},{default:e(()=>[...t[6]||(t[6]=[u("Trusty Tahr (14.04 LTS)",-1)])]),_:1})]),n("li",null,[l(i,{href:"http://www.dedoimedo.com/computers/xubuntu-utopic.html"},{default:e(()=>[...t[7]||(t[7]=[u("Utopic Unicorn (14.10)",-1)])]),_:1})])]),t[38]||(t[38]=n("p",null,"14.04版是一個長期維護的版本，維護週期會持續3年。14.10是最新版本，但是隻提供9個月的維護。",-1)),t[39]||(t[39]=n("p",null,"你選擇了下載站點以後，會提示你選擇32位版本或者64位版本。如果你的電腦是32位，就選32位版本，同樣，如果你的電腦是64位，那就選64位版本。",-1)),n("p",null,[l(i,{href:"http://pcsupport.about.com/od/fixtheproblem/f/32-bit-64-bit-windows.htm"},{default:e(()=>[...t[8]||(t[8]=[u("點擊這裏，有一個教程來教你辨別你的電腦是32位還是64位",-1)])]),_:1}),t[9]||(t[9]=u("。",-1))]),n("p",null,[t[11]||(t[11]=u("可以從",-1)),l(i,{href:"http://www.pendrivelinux.com/universal-usb-installer-easy-as-1-2-3/"},{default:e(()=>[...t[10]||(t[10]=[u("Pendrive Linux網站",-1)])]),_:1}),t[12]||(t[12]=u("下載Universal USB Installer，點擊download鏈接，過一會下載頁面就會彈出來了。",-1))]),t[40]||(t[40]=o('<h3 id="使用universal-usb-installer創建一個xubuntu啓動優盤" tabindex="-1">使用Universal USB Installer創建一個Xubuntu啓動優盤 <a class="header-anchor" href="#使用universal-usb-installer創建一個xubuntu啓動優盤" aria-label="Permalink to “使用Universal USB Installer創建一個Xubuntu啓動優盤”">​</a></h3><p><img src="http://f.tqn.com/y/linux/1/S/-/J/1/uui1l.JPG" alt=""></p><p>下載完Universal USB Installer和Xubuntu以後，運行Universal USB Installer，出現安全警告時，點擊“Accept”。</p><p>Universal USB Installer用來創建一個持久化的Xubuntu啓動優盤。</p><p>第一屏是許可協議。點擊“I Agree”繼續。</p><p><img src="http://f.tqn.com/y/linux/1/S/0/J/1/uui2l.JPG" alt=""></p><p>Universal USB Installer主界面出現以後，從下拉列表中選擇你想要的配置（i.e Xubuntu），第二步，點擊“Browse”選擇你下載的ISO文件的路徑。</p><p>在電腦上插入一個空的優盤，然後選中“Showing all drives”複選框。</p><p>在下拉列表中選中你的優盤（一定要確定選的是正確的盤符哦）。如果優盤不是空的，選中格式化複選框。</p><blockquote><p>注：格式化優盤會清除優盤上的所有數據，首先一定要確認是否以及備份過相關的數據。</p></blockquote><p>在第四步中選擇用於保存“持久化”系統數據的存儲空間大小。</p><p>點擊“Create”按鈕繼續。</p><p><img src="http://f.tqn.com/y/linux/1/S/1/J/1/uu3l.JPG" alt=""></p><p>最後一個界面提示你如果點擊“Yes”，那麼將會直接應用你的配置。</p><p>這是停止安裝的最後一個機會，一定要確定你選了正確的優盤盤符，並且優盤上沒有需要備份的其他文件。</p><p>點擊“Yes”，然後耐心等待優盤創建完成。</p><blockquote><p>注：創建持久化保存空間會花費一些時間，並且這時候進度條不會繼續滾動。</p></blockquote><p>這個過程完成以後，重啓電腦，如果從優盤啓動，就會加載Xubuntu。</p><h3 id="使用ubuntu的startup-disk-creator創建xubuntu啓動優盤" tabindex="-1">使用Ubuntu的Startup Disk Creator創建Xubuntu啓動優盤 <a class="header-anchor" href="#使用ubuntu的startup-disk-creator創建xubuntu啓動優盤" aria-label="Permalink to “使用Ubuntu的Startup Disk Creator創建Xubuntu啓動優盤”">​</a></h3><p><img src="http://f.tqn.com/y/linux/1/S/H/J/1/ubuntustartupdiskcreator.png" alt=""></p><p>如果你已經安裝了Ubuntu，那麼創建持久化USB Xubuntu系統盤的最簡單的辦法就是使用Startup Disk Creator。</p><p>按下超級鍵（Windows鍵），打開Dash，搜索“Startup Disk Creator”，圖標出現以後點擊它。</p>',22)),n("p",null,[t[14]||(t[14]=u("如果你對Ubuntu Dash不太熟悉，你可以",-1)),l(i,{href:"http://linux.about.com/od/howtos/fl/Learn-Ubuntu-The-Unity-Dash.htm"},{default:e(()=>[...t[13]||(t[13]=[u("點擊這裏，查看一個完整的教程",-1)])]),_:1}),t[15]||(t[15]=u("。",-1))]),t[41]||(t[41]=o('<p>Startup Disk Creator使用起來很簡單。</p><p>界面被劃分成兩個部分。上部分指定下載的系統盤路徑，下部分指定安裝的優盤。</p><p>首先，點擊“Other”按鈕，第二步，選擇你所下載的Xubuntu ISO文件。</p><p>然後插入優盤，點擊“Erase”按鈕清除優盤數據。</p><blockquote><p>注：點擊“Erase”會刪除優盤中所有的數據，記得先備份數據。</p></blockquote><p>選中“Stored in reserved extra sapce”單選按鈕，然後拖動“How much”來確定你想要用來存儲“持久化”數據的空間。</p><p>點擊“Make Startup Disk”。</p><p>你創建的過程中，你可能需要輸入幾次你的系統密碼，USB系統盤創建完成以後，你就可以使用它啓動到Xubuntu了。</p><h3 id="使用unetbootin創建持久化的xubuntu系統盤" tabindex="-1">使用UNetbootin創建持久化的Xubuntu系統盤 <a class="header-anchor" href="#使用unetbootin創建持久化的xubuntu系統盤" aria-label="Permalink to “使用UNetbootin創建持久化的Xubuntu系統盤”">​</a></h3><p><img src="http://f.tqn.com/y/linux/1/S/I/J/1/unetbootin1.png" alt=""></p><p>我要介紹的最後一個工具是UNetbootin，這個工具在Windows和Linux上都可以使用。</p><p>個人來説，在Windows系統上面我喜歡用Universal USB Installer，但Linux的話，UNetbootin更合適一些。</p><blockquote><p>注：UNetbootin並不是100%完美的，不是所有的Linux發行版都支持。</p></blockquote>',13)),n("p",null,[t[17]||(t[17]=u("Windows平台可以點擊",-1)),l(i,{href:"http://linux.about.com/od/howtos/ss/How-To-Create-A-UEFI-Bootable-Ubuntu-USB-Drive-Using-Windows.htm"},{default:e(()=>[...t[16]||(t[16]=[u("這裏",-1)])]),_:1}),t[18]||(t[18]=u("下載UNetbootin。",-1))]),t[42]||(t[42]=o("<p>Linux平台可以使用package manager安裝UNetbootin。</p><p>確認你的優盤已經連接到電腦上，確認優盤已經格式化，並且在優盤上沒有其他的數據。</p><p>在Windows平台上運行UNetbootin只需要雙擊可執行程序即可，在Linux運行的話則需要提升權限。</p><p>在Linux上如何運行取決於你使用的是何種桌面環境以及Linux發行版。從命令列運行的話，輸入下列命令：</p><blockquote><p>sudo unetbootin</p></blockquote><p>UNetbootin的界面分為兩個部分。你可以在上半部分選擇一個Linux發行版，然後下載它，如果已經下載了某個發行版，可以在下半部分選擇已經下載的系統盤。</p><p>點擊“Diskimage”單選框，然後點擊三個點的按鈕。找到已經下載的Xubuntu ISO文件。路徑會顯示到按鈕旁邊的文本框裏面。</p><p>設置“Space used to preserve files across reboots”的值，來指定你想要用來存儲“持久化”數據的空間大小。</p><p>類型選擇USB drive，然後選擇優盤的盤符。</p><p>點擊“OK”來創建一個持久化Xubuntu啓動優盤。</p><p>創建的過程要花一些時間，創建完成以後，你就可以通過優盤啓動到Xubuntu系統了。</p>",11)),n("p",null,[t[20]||(t[20]=u("如果你想要創建一個支持UEFI的Xubuntu啓動優盤，",-1)),l(i,{href:"http://linux.about.com/od/howtos/ss/How-To-Create-A-UEFI-Bootable-Ubuntu-USB-Drive-Using-Windows.htm"},{default:e(()=>[...t[19]||(t[19]=[u("照着這個教程來做",-1)])]),_:1}),t[21]||(t[21]=u("，只需要把Ubuntu ISO替換為Xubuntu ISO就可以了。",-1))]),n("p",null,[t[23]||(t[23]=u("via : ",-1)),l(i,{href:"http://linux.about.com/od/howtos/ss/How-To-Create-A-Persistent-Bootable-Xubuntu-Linux-USB-Drive.htm"},{default:e(()=>[...t[22]||(t[22]=[u("http://linux.about.com/od/howtos/ss/How-To-Create-A-Persistent-Bootable-Xubuntu-Linux-USB-Drive.htm",-1)])]),_:1})]),n("p",null,[t[27]||(t[27]=u("作者：",-1)),l(i,{href:"http://linux.about.com/bio/Gary-Newell-132058.htm"},{default:e(()=>[...t[24]||(t[24]=[u("Gary Newell",-1)])]),_:1}),t[28]||(t[28]=u(" 譯者：",-1)),l(i,{href:"https://github.com/Zhouj-sh"},{default:e(()=>[...t[25]||(t[25]=[u("zhouj-sh",-1)])]),_:1}),t[29]||(t[29]=u(" 校對：",-1)),l(i,{href:"https://github.com/carolinewuyan"},{default:e(()=>[...t[26]||(t[26]=[u("Caroline",-1)])]),_:1})]),n("p",null,[t[32]||(t[32]=u("本文由 ",-1)),l(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[30]||(t[30]=[u("LCTT",-1)])]),_:1}),t[33]||(t[33]=u(" 原創翻譯，",-1)),l(i,{href:"http://linux.cn/"},{default:e(()=>[...t[31]||(t[31]=[u("Linux中國",-1)])]),_:1}),t[34]||(t[34]=u(" 榮譽推出",-1))])])}const w=r(b,[["render",d]]);export{B as __pageData,w as default};
